+struct qcom_pas_cluster {
+	struct kref kref;
+	struct list_head node;
+	struct device_node *root_node;
+	struct mutex lock;
+	struct list_head members;
+	wait_queue_head_t wq;
+	bool booted;
+	bool restart_pending;
+};
